import{_ as d,o as r,c as e,a0 as a}from"./chunks/framework.ZoVXsKRZ.js";const b=JSON.parse('{"title":"日本麻将「立直麻将」完全入门","description":"","frontmatter":{"lastUpdated":true},"headers":[],"relativePath":"skills/riichi.md","filePath":"skills/riichi.md","lastUpdated":1784794489000}'),o={name:"skills/riichi.md"};function n(s,t,l,i,h,g){return r(),e("div",null,[...t[0]||(t[0]=[a('<h1 id="日本麻将「立直麻将」完全入门" tabindex="-1">日本麻将「立直麻将」完全入门 <a class="header-anchor" href="#日本麻将「立直麻将」完全入门" aria-label="Permalink to &quot;日本麻将「立直麻将」完全入门&quot;">​</a></h1><p>日本麻将（リーチ麻雀 / 立直麻将）是日本最主流的麻将玩法，也是二次元玩家最熟悉的规则（《雀魂》《天才麻将少女》等都是日麻）。日麻强调防守和策略深度，被誉为&quot;最优雅的麻将&quot;。</p><h2 id="基本参数" tabindex="-1">基本参数 <a class="header-anchor" href="#基本参数" aria-label="Permalink to &quot;基本参数&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>说明</th></tr></thead><tbody><tr><td><strong>人数</strong></td><td>4 人（也有 3 人规则）</td></tr><tr><td><strong>牌数</strong></td><td>136 张（万、筒、条 + 字牌，无花牌）</td></tr><tr><td><strong>番数门槛</strong></td><td><strong>必须至少有一种役（番型）才能胡牌</strong></td></tr><tr><td><strong>分数</strong></td><td>起始 25000 点，按番数和符数计分</td></tr><tr><td><strong>振听</strong></td><td>自己打过的牌不能胡别人的</td></tr></tbody></table><hr><h2 id="日麻三大特色" tabindex="-1">日麻三大特色 <a class="header-anchor" href="#日麻三大特色" aria-label="Permalink to &quot;日麻三大特色&quot;">​</a></h2><h3 id="_1-有役才能胡" tabindex="-1">1. 有役才能胡 <a class="header-anchor" href="#_1-有役才能胡" aria-label="Permalink to &quot;1. 有役才能胡&quot;">​</a></h3><p>日麻最大的门槛：<strong>必须至少满足一种「役」才能胡牌。</strong> 最常见的入门役：</p><table tabindex="0"><thead><tr><th>役名</th><th>说明</th><th style="text-align:center;">番数</th><th>条件</th></tr></thead><tbody><tr><td><strong>立直（リーチ）</strong></td><td>门清听牌后宣言</td><td style="text-align:center;">1</td><td>不吃不碰，听牌时交出 1000 点棒</td></tr><tr><td><strong>断幺九</strong></td><td>无 1、9 和字牌</td><td style="text-align:center;">1</td><td>手牌全是 2~8</td></tr><tr><td><strong>平和</strong></td><td>全顺子 + 两面听 + 非字牌将</td><td style="text-align:center;">1</td><td>必须门清</td></tr><tr><td><strong>一杯口</strong></td><td>两组相同的顺子</td><td style="text-align:center;">1</td><td>必须门清</td></tr><tr><td><strong>役牌</strong></td><td>有场风/自风/三元牌的刻子</td><td style="text-align:center;">1</td><td>如东家碰东风</td></tr><tr><td><strong>混一色</strong></td><td>一种花色 + 字牌</td><td style="text-align:center;">2-3</td><td>门清 3 番，副露 2 番</td></tr><tr><td><strong>清一色</strong></td><td>全部同花色</td><td style="text-align:center;">5-6</td><td>门清 6 番，副露 5 番</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">新手保底策略</p><p>立直（1番）+ 断幺九（1番）+ 平和（1番）可以叠加！门清状态下立直，经常能做出 3-4 番的牌。</p></div><h3 id="_2-振听-フリテン-规则" tabindex="-1">2. 振听（フリテン）规则 <a class="header-anchor" href="#_2-振听-フリテン-规则" aria-label="Permalink to &quot;2. 振听（フリテン）规则&quot;">​</a></h3><p><strong>振听是日麻最独特的规则，也是最容易被忽略的陷阱：</strong></p><ul><li><strong>舍牌振听</strong>：自己打过的牌，不能胡别人打的同一张</li><li><strong>立直后振听</strong>：立直后别人打的牌你没胡，此后永远不能胡那张</li><li><strong>临时振听</strong>：别人打的牌你没胡（不管什么原因），本轮内其他人再打也不能胡</li></ul><div class="danger custom-block"><p class="custom-block-title">振听陷阱</p><p>经常有新手不小心振听，等了半天才发现胡不了。<strong>养成习惯：摸牌前先检查自己是否振听。</strong></p></div><h3 id="_3-点数制" tabindex="-1">3. 点数制 <a class="header-anchor" href="#_3-点数制" aria-label="Permalink to &quot;3. 点数制&quot;">​</a></h3><p>日麻不用番数直接算钱，而是用「番」和「符」计算点数：</p><table tabindex="0"><thead><tr><th style="text-align:center;">番数</th><th>名称</th><th>子家点数</th><th>亲家点数</th></tr></thead><tbody><tr><td style="text-align:center;">1 番</td><td>—</td><td>~1000 点</td><td>~1500 点</td></tr><tr><td style="text-align:center;">2 番</td><td>—</td><td>~2000 点</td><td>~2900 点</td></tr><tr><td style="text-align:center;">3 番</td><td>—</td><td>~3900 点</td><td>~5800 点</td></tr><tr><td style="text-align:center;">4-5 番</td><td>満貫</td><td>8000 点</td><td>12000 点</td></tr><tr><td style="text-align:center;">6-7 番</td><td>跳満</td><td>12000 点</td><td>18000 点</td></tr><tr><td style="text-align:center;">8-10 番</td><td>倍満</td><td>16000 点</td><td>24000 点</td></tr><tr><td style="text-align:center;">11-12 番</td><td>三倍満</td><td>24000 点</td><td>36000 点</td></tr><tr><td style="text-align:center;">13 番+</td><td>役満</td><td>32000 点</td><td>48000 点</td></tr></tbody></table><hr><h2 id="役満-最高番型" tabindex="-1">役満（最高番型） <a class="header-anchor" href="#役満-最高番型" aria-label="Permalink to &quot;役満（最高番型）&quot;">​</a></h2><p>日麻最高级别的番型，出现的概率极低，胡到一次能吹一年：</p><table tabindex="0"><thead><tr><th>役満</th><th>说明</th></tr></thead><tbody><tr><td><strong>国士无双</strong></td><td>十三种幺九牌 + 任一对（对应中国的十三幺）</td></tr><tr><td><strong>四暗刻</strong></td><td>四组暗刻 + 一对将（全靠自己摸）</td></tr><tr><td><strong>大三元</strong></td><td>中发白各一组刻子</td></tr><tr><td><strong>字一色</strong></td><td>全部由字牌组成</td></tr><tr><td><strong>绿一色</strong></td><td>全部由 2/3/4/6/8 条 + 发组成</td></tr><tr><td><strong>九莲宝灯</strong></td><td>1112345678999 + 同花色任一张</td></tr><tr><td><strong>天和</strong></td><td>庄家起手即胡牌</td></tr><tr><td><strong>地和</strong></td><td>闲家第一巡摸牌即胡牌</td></tr></tbody></table><hr><h2 id="与中麻的核心区别" tabindex="-1">与中麻的核心区别 <a class="header-anchor" href="#与中麻的核心区别" aria-label="Permalink to &quot;与中麻的核心区别&quot;">​</a></h2><table tabindex="0"><thead><tr><th>对比</th><th>日本麻将</th><th>中国麻将（广东）</th></tr></thead><tbody><tr><td>胡牌门槛</td><td>必须有役（番型）</td><td>0 番也能鸡胡</td></tr><tr><td>振听</td><td>✅ 有，很严格</td><td>❌ 无</td></tr><tr><td>花牌</td><td>❌ 无</td><td>各地区不同</td></tr><tr><td>食替</td><td>❌ 不能碰了马上换牌</td><td>✅ 各地区不同</td></tr><tr><td>流局</td><td>有多种流局规则</td><td>摸完就算流局</td></tr><tr><td>分数</td><td>25000 点起，按番符计算</td><td>按番数/倍数计算</td></tr></tbody></table><hr><h2 id="推荐平台" tabindex="-1">推荐平台 <a class="header-anchor" href="#推荐平台" aria-label="Permalink to &quot;推荐平台&quot;">​</a></h2><table tabindex="0"><thead><tr><th>平台</th><th>特点</th><th>适合人群</th></tr></thead><tbody><tr><td><strong>雀魂麻将（Majsoul）</strong></td><td>二次元画风，中文界面，国人最多</td><td>新手入门首选</td></tr><tr><td><strong>天凤（Tenhou）</strong></td><td>日本人最多，最硬核</td><td>进阶玩家</td></tr><tr><td><strong>麻雀格斗俱乐部</strong></td><td>街机风格，节奏快</td><td>休闲玩家</td></tr></tbody></table><hr><h2 id="新手快速上手路径" tabindex="-1">新手快速上手路径 <a class="header-anchor" href="#新手快速上手路径" aria-label="Permalink to &quot;新手快速上手路径&quot;">​</a></h2><ol><li><strong>下载雀魂</strong> → 玩&quot;友人场&quot;熟悉基本操作</li><li><strong>记住 5 个基础役</strong>：立直、断幺九、平和、役牌、混一色</li><li><strong>理解振听</strong> → 这是新手最大的坑</li><li><strong>学会防守</strong> → 对手立直后，打安全牌（现物/筋牌）</li><li><strong>多看高手打</strong> → 在 B 站/Youtube 搜&quot;日麻教学&quot;</li></ol><p>日麻入门难但精通后极有深度，加油！🀄</p><hr><p><em>日麻规则精细，以上为基础入门。详细规则可参考日本麻将联盟官方手册。</em></p>',33)])])}const u=d(o,[["render",n]]);export{b as __pageData,u as default};
